import{_ as p,a0 as e,w as r,s as u,ao as o,I as s,x as a,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"在你開始使用 Kali Linux 之前必須知道的事情 | LCTT x X-CMD","titleTemplate":false,"description":"在你開始使用 Kali Linux 之前必須知道的事情 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在你開始使用 Kali Linux 之前必須知道的事情 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在你開始使用 Kali Linux 之前必須知道的事情 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181015 Kali Linux- What You Must Know Before Using it - FOSS Post","title":"在你開始使用 Kali Linux 之前必須知道的事情","tag":"201811","desc":""},"relativePath":"201811/20181015 Kali Linux- What You Must Know Before Using it - FOSS Post.md","filePath":"[post].md"}'),x={name:"201811/20181015 Kali Linux- What You Must Know Before Using it - FOSS Post.md"};function d(L,i,K,f,m,g){const t=e("Link");return r(),u("div",null,[i[26]||(i[26]=o('<h1 id="在你開始使用-kali-linux-之前必須知道的事情" tabindex="-1">在你開始使用 Kali Linux 之前必須知道的事情 <a class="header-anchor" href="#在你開始使用-kali-linux-之前必須知道的事情" aria-label="Permalink to “在你開始使用 Kali Linux 之前必須知道的事情”">​</a></h1><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2018/10/kali-linux.png?fit=1237%2C527&amp;ssl=1" alt=""></p><p>Kali Linux 在滲透測試和白帽子方面是業界領先的 Linux 發行版。默認情況下，該發行版附帶了大量入侵和滲透的工具和軟件，並且在全世界都得到了廣泛認可。即使在那些甚至可能不知道 Linux 是什麼的 Windows 用户中也是如此。</p><p>由於後者的原因（LCTT 譯註：Windows 用户），許多人都試圖單獨使用 Kali Linux，儘管他們甚至不瞭解 Linux 系統的基礎知識。原因可能各不相同，有的為了玩樂，有的是為了取悦女友而偽裝成黑客，有的僅僅是試圖破解鄰居的 WiFi 網絡以免費上網。如果你打算使用 Kali Linux，記住，所有的這些都是不好的事情。</p><p>在計劃使用 Kali Linux 之前，你應該瞭解一些提示。</p><h3 id="kali-linux-不適合初學者" tabindex="-1">Kali Linux 不適合初學者 <a class="header-anchor" href="#kali-linux-不適合初學者" aria-label="Permalink to “Kali Linux 不適合初學者”">​</a></h3><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2018/10/Kali-Linux-000.png?resize=850%2C478&amp;ssl=1" alt=""></p><p><em>Kali Linux 默認 GNOME 桌面</em></p><p>如果你是幾個月前剛開始使用 Linux 的人，或者你認為自己的知識水平低於平均水平，那麼 Kali Linux 就不適合你。如果你打算問“如何在 Kali 上安裝 Steam？如何讓我的打印機在 Kali 上工作？如何解決 Kali 上的 APT 源錯誤？”這些東西，那麼 Kali Linux 並不適合你。</p><p>Kali Linux 主要面向想要運行滲透測試套件的專家或想要學習成為白帽子和數字取證的人。但即使你屬於後者，普通的 Kali Linux 用户在日常使用時也會遇到很多麻煩。他還被要求以非常謹慎的方式使用工具和軟件，而不僅僅是“讓我們安裝並運行一切”。每一個工具必須小心使用，你安裝的每一個軟件都必須仔細檢查。</p>',10)),s("p",null,[i[1]||(i[1]=s("strong",null,"建議閲讀：",-1)),i[2]||(i[2]=a()),n(t,{href:"https://fosspost.org/articles/what-are-the-components-of-a-linux-distribution"},{default:l(()=>[...i[0]||(i[0]=[a("Linux 系統的組件有什麼?",-1)])]),_:1})]),i[27]||(i[27]=o('<p>普通 Linux 用户都無法自如地使用它。一個更好的方法是花幾周時間學習 Linux 及其守護進程、服務、軟件、發行版及其工作方式，然後觀看幾十個關於白帽子攻擊的視頻和課程，然後再嘗試使用 Kali 來應用你學習到的東西。</p><h3 id="它會讓你被黑客攻擊" tabindex="-1">它會讓你被黑客攻擊 <a class="header-anchor" href="#它會讓你被黑客攻擊" aria-label="Permalink to “它會讓你被黑客攻擊”">​</a></h3><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2018/10/Kali-Linux-001.png?resize=850%2C478&amp;ssl=1" alt=""></p><p><em>Kali Linux 入侵和測試工具</em></p><p>在普通的 Linux 系統中，普通用户有一個賬户，而 root 用户也有一個單獨的賬號。但在 Kali Linux 中並非如此。Kali Linux 默認使用 root 賬户，不提供普通用户賬户。這是因為 Kali 中幾乎所有可用的安全工具都需要 root 權限，並且為了避免每分鐘要求你輸入 root 密碼，所以這樣設計。</p><p>當然，你可以簡單地創建一個普通用户賬户並開始使用它。但是，這種方式仍然不推薦，因為這不是 Kali Linux 系統設計的工作方式。使用普通用户在使用程序，打開端口，調試軟件時，你會遇到很多問題，你會發現為什麼這個東西不起作用，最終卻發現它是一個奇怪的權限錯誤。另外每次在系統上做任何事情時，你會被每次運行工具都要求輸入密碼而煩惱。</p><p>現在，由於你被迫以 root 用户身份使用它，因此你在系統上運行的所有軟件也將以 root 權限運行。如果你不知道自己在做什麼，那麼這很糟糕，因為如果 Firefox 中存在漏洞，並且你訪問了一個受感染的網站，那麼黑客能夠在你的 PC 上獲得全部 root 權限併入侵你。如果你使用的是普通用户賬户，則會受到限制。此外，你安裝和使用的某些工具可能會在你不知情的情況下打開端口並泄露信息，因此如果你不是非常小心，人們可能會以你嘗試入侵他們的方式入侵你。</p><p>如果你曾經訪問過與 Kali Linux 相關的 Facebook 羣組，你會發現這些羣組中幾乎有四分之一的帖子是人們在尋求幫助，因為有人入侵了他們。</p><h3 id="它可以讓你入獄" tabindex="-1">它可以讓你入獄 <a class="header-anchor" href="#它可以讓你入獄" aria-label="Permalink to “它可以讓你入獄”">​</a></h3><p>Kali Linux 只是提供了軟件。那麼，如何使用它們完全是你自己的責任。</p><p>在世界上大多數發達國家，使用針對公共 WiFi 網絡或其他設備的滲透測試工具很容易讓你入獄。現在不要以為你使用了 Kali 就無法被跟蹤，許多系統都配置了複雜的日誌記錄設備來簡單地跟蹤試圖監聽或入侵其網絡的人，你可能無意間成為其中的一個，那麼它會毀掉你的生活。</p><p>永遠不要對不屬於你的設備或網絡使用 Kali Linux 系統，也不要明確允許對它們進行入侵。如果你説你不知道你在做什麼，在法庭上它不會被當作藉口來接受。</p><h3 id="修改了的內核和軟件" tabindex="-1">修改了的內核和軟件 <a class="header-anchor" href="#修改了的內核和軟件" aria-label="Permalink to “修改了的內核和軟件”">​</a></h3>',13)),s("p",null,[i[4]||(i[4]=a("Kali ",-1)),n(t,{href:"https://www.kali.org/news/kali-linux-rolling-edition-2016-1/"},{default:l(()=>[...i[3]||(i[3]=[a("基於",-1)])]),_:1}),i[5]||(i[5]=a(" Debian（“測試”分支，這意味着 Kali Linux 使用滾動發佈模型），因此它使用了 Debian 的大部分軟件體系結構，你會發現 Kali Linux 中的大部分軟件跟 Debian 中的沒什麼區別。",-1))]),i[28]||(i[28]=o(`<p>但是，Kali 修改了一些包來加強安全性並修復了一些可能的漏洞。例如，Kali 使用的 Linux 內核被打了補丁，允許在各種設備上進行無線注入。這些補丁通常在普通內核中不可用。此外，Kali Linux 不依賴於 Debian 服務器和鏡像，而是通過自己的服務器構建軟件包。以下是最新版本中的默認軟件源：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>deb http://http.kali.org/kali kali-rolling main contrib non-free</span></span>
<span class="line"><span>deb-src http://http.kali.org/kali kali-rolling main contrib non-free</span></span></code></pre></div>`,2)),s("p",null,[i[8]||(i[8]=a("這就是為什麼，對於某些特定的軟件，當你在 Kali Linux 和 Fedora 中使用相同的程序時，你會發現不同的行為。你可以從 ",-1)),n(t,{href:"http://git.kali.org"},{default:l(()=>[...i[6]||(i[6]=[a("git.kali.org",-1)])]),_:1}),i[9]||(i[9]=a(" 中查看 Kali Linux 軟件的完整列表。你還可以在 Kali Linux（GNOME）上找到我們",-1)),n(t,{href:"https://paste.ubuntu.com/p/bctSVWwpVw/"},{default:l(()=>[...i[7]||(i[7]=[a("自己生成的已安裝包列表",-1)])]),_:1}),i[10]||(i[10]=a("。",-1))]),i[29]||(i[29]=o('<p>更重要的是，Kali Linux 官方文檔極力建議不要添加任何其他第三方軟件倉庫，因為 Kali Linux 是一個滾動發行版，並且依賴於 Debian 測試分支，由於依賴關係衝突和包鈎子，所以你很可能只是添加一個新的倉庫源就會破壞系統。</p><h3 id="不要安裝-kali-linux" tabindex="-1">不要安裝 Kali Linux <a class="header-anchor" href="#不要安裝-kali-linux" aria-label="Permalink to “不要安裝 Kali Linux”">​</a></h3><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2018/10/Kali-Linux-002.png?resize=750%2C504&amp;ssl=1" alt=""></p><p><em>使用 Kali Linux 在 fosspost.org 上運行 wpscan</em></p><p>我在極少數情況下使用 Kali Linux 來測試我部署的軟件和服務器。但是，我永遠不敢安裝它並將其用作主系統。</p><p>如果你要將其用作主系統，那麼你必須保留自己的個人文件、密碼、數據以及系統上的所有內容。你還需要安裝大量日常使用的軟件，以解放你的生活。但正如我們上面提到的，使用 Kali Linux 是非常危險的，應該非常小心地進行，如果你被入侵了，你將丟失所有數據，並且可能會暴露給更多的人。如果你在做一些不合法的事情，你的個人信息也可用於跟蹤你。如果你不小心使用這些工具，那麼你甚至可能會毀掉自己的數據。</p><p>即使是專業的白帽子也不建議將其作為主系統安裝，而是通過 USB 使用它來進行滲透測試工作，然後再回到普通的 Linux 發行版。</p><h3 id="底線" tabindex="-1">底線 <a class="header-anchor" href="#底線" aria-label="Permalink to “底線”">​</a></h3><p>正如你現在所看到的，使用 Kali 並不是一個輕鬆的決定。如果你打算成為一個白帽子，你需要使用 Kali 來學習，那麼在學習了基礎知識並花了幾個月的時間使用普通 Linux 系統之後再來學習 Kali。但是小心你正在做的事情，以避免遇到麻煩。</p><p>如果你打算使用 Kali，或者你需要任何幫助，我很樂意在評論中聽到你的想法。</p><hr>',11)),s("p",null,[i[12]||(i[12]=a("via: ",-1)),n(t,{href:"https://fosspost.org/articles/must-know-before-using-kali-linux"},{default:l(()=>[...i[11]||(i[11]=[a("https://fosspost.org/articles/must-know-before-using-kali-linux",-1)])]),_:1})]),s("p",null,[i[17]||(i[17]=a("作者：",-1)),n(t,{href:"https://fosspost.org/author/mhsabbagh"},{default:l(()=>[...i[13]||(i[13]=[a("M.Hanny Sabbagh",-1)])]),_:1}),i[18]||(i[18]=a(" 選題：",-1)),n(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...i[14]||(i[14]=[a("lujun9972",-1)])]),_:1}),i[19]||(i[19]=a(" 譯者：",-1)),n(t,{href:"https://github.com/MjSeven"},{default:l(()=>[...i[15]||(i[15]=[a("MjSeven",-1)])]),_:1}),i[20]||(i[20]=a(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:l(()=>[...i[16]||(i[16]=[a("wxy",-1)])]),_:1})]),s("p",null,[i[23]||(i[23]=a("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[21]||(i[21]=[a("LCTT",-1)])]),_:1}),i[24]||(i[24]=a(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:l(()=>[...i[22]||(i[22]=[a("Linux中國",-1)])]),_:1}),i[25]||(i[25]=a(" 榮譽推出",-1))])])}const h=p(x,[["render",d]]);export{k as __pageData,h as default};
